"@media (max-width: 768px) {
  /* Bento Grid ở dạng 2 cột trên Mobile để tối ưu hóa diện tích cuộn */
  .bento-grid {
    display: grid !important;
    grid-template-columns: repeat(2, 1fr) !important;
    gap: 12px !important;
  }

  /* Thay đổi thứ tự hiển thị (order) để ghép cặp hoàn hảo các card span 1, lấp đầy các khoảng trống */
  .bento-card:nth-child(1) { order: 1 !important; } /* Card 1: Camera AI (span 2) */
  .bento-card:nth-child(2) { order: 2 !important; } /* Card 2: 100% Free (span 1) */
  .bento-card:nth-child(5) { order: 3 !important; } /* Card 5: Water Tracker (span 1) -> Ghép cặp hàng 2 */
  .bento-card:nth-child(3) { order: 4 !important; } /* Card 3: Voice AI (span 2) */
  .bento-card:nth-child(4) { order: 5 !important; } /* Card 4: Macros Rings (span 2) */
  .bento-card:nth-child(6) { order: 6 !important; } /* Card 6: Streak (span 1) */
  .bento-card:nth-child(8) { order: 7 !important; } /* Card 8: Auth Sync (span 1) -> Ghép cặp hàng 5 */
  .bento-card:nth-child(7) { order: 8 !important; } /* Card 7: AI Recipes (span 2) -> Đưa xuống cuối cùng */

  /* Định nghĩa span cho các loại card trên mobile */
  .bento-card.card-wide,
  .bento-card.card-tall {
    grid-column: span 2 !important;
    grid-row: span 1 !important;
  }

  .bento-card:nth-child(2), /* 100% Free Quota */
  .bento-card:nth-child(5), /* Water Tracker */
