"/* ==================== 3. TỐI ƯU ĐẶC BIỆT CHO SMARTPHONE NHỎ (SCREEN <= 576px) ==================== */
@media (max-width: 576px) {
  .bento-grid {
    grid-template-columns: 1fr !important; /* Quay về 1 cột dọc để tránh bóp nghẹt chiều ngang */
    gap: 12px !important;
  }

  .bento-card {
    grid-column: span 1 !important; /* Tất cả chiếm full chiều rộng */
    display: flex !important;
    flex-direction: row !important; /* Chuyển sang layout nằm ngang */
    align-items: center !important;
    justify-content: space-between !important;
    padding: 12px 14px !important;
    height: auto !important;
    min-height: unset !important;
  }

  .bento-content-wrap {
    max-width: 65% !important; /* Text chiếm 65% */
    flex: 1 !important;
  }

  .bento-card h3 {
    font-size: 0.95rem !important;
    margin-bottom: 4px !important;
  }

  .bento-card p {
    font-size: 0.72rem !important;
    line-height: 1.4 !important;
  }

  /* Ẩn bong bóng thoại và mascot để tối ưu không gian */
  .bento-mochi-speech,
  .bento-mascot-img {
    display: none !important;
  }

  /* 3.1. Card 1: Camera AI Scan */
  .bento-card:nth-child(1) .bento-phone-mockup {
    width: 80px !important;
    height: 110px !important;
    margin: 0 !important;
    flex-shrink: 0 !important;
  }
  .bento-card:nth-child(1) .bento-phone-mockup .bento-mockup-img {
    width: 100% !important;
    height: 100% !important;
    object-fit: contain !important;
  }

  /* 3.2. Card 2: 100% Free Quota */
  .bento-quota-visual {
    width: 100px !important;
    margin: 0 !important;
    flex-shrink: 0 !important;
