"/* ═══════════════════════════════════════════════════════════════
   BENTO GRID MOBILE OVERRIDE — FILE NÀY LOAD CUỐI CÙNG
   Mục đích: Override triệt để layout Bento Grid cho di động nhỏ
   ═══════════════════════════════════════════════════════════════ */

@media (max-width: 576px) {
  /* === GRID: Ép 1 cột dọc === */
  .bento-grid {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 10px !important;
  }

  /* === RESET TẤT CẢ CARD: 1 cột, flex-column, không order ===
       Liệt kê nth-child để thắng specificity 0-2-0 từ styles.css */
  .bento-card,
  .bento-card:nth-child(1),
  .bento-card:nth-child(2),
  .bento-card:nth-child(3),
  .bento-card:nth-child(4),
  .bento-card:nth-child(5),
  .bento-card:nth-child(6),
  .bento-card:nth-child(7),
  .bento-card:nth-child(8),
  .bento-card:nth-child(9) {
    grid-column: span 1 !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    justify-content: flex-start !important;
    padding: 14px !important;
    height: auto !important;
    min-height: unset !important;
    max-height: none !important;
    order: unset !important;
    width: auto !important;
    position: relative !important;
    overflow: hidden !important;
  }

  /* Override card-wide / card-tall (specificity 0-3-0) */
  .bento-card.card-wide,
  .bento-card.card-tall,
