```javascript
function findOverlappingTexts() {
  const elements = Array.from(document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, span, label, a, li, button'));
  const rects = elements.map(el => {
    const rect = el.getBoundingClientRect();
    return { el, rect, text: el.innerText ? el.innerText.trim() : \"\" };
  }).filter(item => item.text.length > 0 && item.rect.width > 0 && item.rect.height > 0);

  const overlaps = [];
  for (let i = 0; i < rects.length; i++) {
    for (let j = i + 1; j < rects.length; j++) {
      const r1 = rects[i].rect;
      const r2 = rects[j].rect;
      const isOverlapping = !(r1.right <= r2.left || r1.left >= r2.right || r1.bottom <= r2.top || r1.top >= r2.bottom);
      if (isOverlapping) {
        if (!rects[i].el.contains(rects[j].el) && !rects[j].el.contains(rects[i].el)) {
          // Kiểm tra xem có phải do absolute positioning đè lên nhau không
          overlaps.push({
            text1: rects[i].text.substring(0, 30),
            text2: rects[j].text.substring(0, 30),
            selector1: rects[i].el.tagName + '.' + rects[i].el.className,
            selector2: rects[j].el.tagName + '.' + rects[j].el.className
          });
        }
      }
    }
  }
  return overlaps;
}
