+      card.addEventListener("mousemove", (e) => {
+        const rect = card.getBoundingClientRect();
+        const x = e.clientX - rect.left; 
+        const y = e.clientY - rect.top;  
+        
+        const centerX = rect.width / 2;
+        const centerY = rect.height / 2;
+        
+        // Giới hạn góc quay tối đa là 7 độ để hiệu ứng tinh tế, không bị quá lố
+        const rotateX = ((centerY - y) / centerY) * 7; 
+        const rotateY = ((x - centerX) / centerX) * 7;
+        
+        card.style.transform = `rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(1.025)`;
+        card.style.boxShadow = "0 25px 50px rgba(0,0,0,0.45), 0 0 30px rgba(15, 159, 104, 0.18)";
+
+        // Tính toán tọa độ Sheen ánh sáng chạy động trên bề mặt điện thoại mockup
+        if (card === simPhone) {
+          const sheenX = (x / rect.width) * 100;
+          const sheenY = (y / rect.height) * 100;
+          card.style.setProperty("--sheen-x", `${sheenX}%`);
+          card.style.setProperty("--sheen-y", `${sheenY}%`);
+        }
+      });
+
+      card.addEventListener("mouseleave", () => {
+        card.style.transform = "rotateX(0deg) rotateY(0deg) scale(1)";
+        card.style.boxShadow = "none";
