"/* --- E. Magnetic Buttons Transition Support --- */
.btn-primary, .btn-secondary, .google-btn-mockup, .bento-interactive-btn, .camera-toggle-btn {
  transition: transform 0.2s cubic-bezier(0.25, 1, 0.5, 1), box-shadow 0.3s ease, background 0.3s ease;
}

