/* 1. Mouse Spotlight Glow neon mờ ảo riêng biệt cho từng Bento Card */
.bento-card[data-glow-card] {
  --spotlight-color: rgba(255, 255, 255, 0.05);
}
.bento-card[data-glow-card]:nth-child(1) {
  --spotlight-color: rgba(15, 159, 104, 0.12); /* Ngọc bích */
}
#bentoCardRecipe {
  --spotlight-color: rgba(212, 175, 55, 0.1); /* Vàng hổ phách lai */
}
.bento-card[data-glow-card]:nth-child(4), 
.bento-card.card-wide:nth-of-type(2) {
  --spotlight-color: rgba(168, 85, 247, 0.12); /* Tím */
}
#bentoCardStreak {
  --spotlight-color: rgba(245, 158, 11, 0.12); /* Hổ phách */
}

.bento-card-glow {
  position: absolute;
  inset: 0;
