args.TargetContent:
"  // --- 1. BENTO SPOTLIGHT DYNAMIC MOUSE GLOW ---
  // Lý do thiết kế: Tạo hiệu ứng chiều sâu quang học 3D, bám đuổi theo tọa độ chuột
  // trên PC giúp tăng tính sang trọng, sinh động và đắt tiền cho giao diện Bento Glassmorphism.
  function initBentoSpotlightInteractive() {
    try {
      // Chỉ chạy trên thiết bị có chuột (PC) để đảm bảo hiệu năng tối ưu
      if (window.innerWidth < 992) return;

      const glowCards = document.querySelectorAll(".bento-card[data-glow-card]");
      glowCards.forEach(card => {
        if (!card) return;

        // Đảm bảo card có phần tử glow
        let glow = card.querySelector(".bento-card-glow");
        if (!glow) {
          glow = document.createElement("div");
          glow.className = "bento-card-glow";
          card.appendChild(glow);
        }

        card.addEventListener("mousemove", (e) => {
          const rect = card.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const y = e.clientY - rect.top;
          card.style.setProperty("--mouse-x", `${x}px`);
          card.style.setProperty("--mouse-y", `${y}px`);
        });
      });
    } catch (err) {
      console.error("Lỗi khởi tạo Bento Spotlight:", err);
    }
  }"

