  transform: translateY(-4px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35);
}

/* 1. Tone Xanh ngọc (Card 1, Card 5) */
#bentoCardScan:hover,
.bento-card:nth-child(5):hover {
  border-color: rgba(15, 159, 104, 0.65) !important;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35), 0 0 20px rgba(15, 159, 104, 0.25) !important;
}

/* 2. Tone Lam ngọc / Xanh dương (Card 2, Card 8) */
.bento-card:nth-child(2):hover,
.bento-card:nth-child(8):hover {
  border-color: rgba(50, 215, 240, 0.65) !important;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35), 0 0 20px rgba(50, 215, 240, 0.25) !important;
}

/* 3. Tone Tím Neon (Card 3, Card 4) */
.bento-card.card-tall:hover,
.bento-card:has(.bento-mini-rings):hover {
  border-color: rgba(157, 124, 255, 0.65) !important;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35), 0 0 20px rgba(157, 124, 255, 0.25) !important;
}

/* 4. Tone Vàng Kim (Card 6) */
#bentoCardStreak:hover {
  border-color: rgba(212, 175, 55, 0.65) !important;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35), 0 0 20px rgba(212, 175, 55, 0.25) !important;
}

/* 5. Tone Cam Hổ phách (Card 7) */
#bentoCardRecipe:hover {
  border-color: rgba(255, 115, 0, 0.65) !important;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35), 0 0 20px rgba(255, 115, 0, 0.25) !important;
}"

