"/* ═══ 2. Custom Cursor & Glowing Aura Canvas ═══ */
#particleCanvas {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 99999;
}

.custom-cursor-glow {
  position: fixed;
  top: 0;
  left: 0;
  width: 240px;
  height: 240px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(15, 159, 104, 0.08) 0%, transparent 70%);
  pointer-events: none;
  transform: translate(-50%, -50%);
  z-index: 99998;
  mix-blend-mode: screen;
  transition: opacity 0.5s ease;
  opacity: 0;
}
body:hover .custom-cursor-glow {
  opacity: 1;
}
body.light-theme .custom-cursor-glow {
  background: radial-gradient(circle, rgba(15, 159, 104, 0.04) 0%, transparent 70%);
}"

